//! Auto-generated ARGB32 pixmap data for tray icons.
//! Format: BGRA (little-endian ARGB32).
//! Generated from data/icons/hicolor/<size>x<size>/apps/jotta-desktop-<state>.png

#![allow(dead_code)]

use jotta_core::status::State;
use ksni::Icon;

/// Return the best pixmap set for a given state (24x24 preferred).
pub fn icon_for_state(state: State) -> Vec<Icon> {
    match state {
        State::Idle => vec![
            Icon { width: 16, height: 16, data: PIXMAP_IDLE_16_DATA.to_vec() },
            Icon { width: 22, height: 22, data: PIXMAP_IDLE_22_DATA.to_vec() },
            Icon { width: 24, height: 24, data: PIXMAP_IDLE_24_DATA.to_vec() },
            Icon { width: 32, height: 32, data: PIXMAP_IDLE_32_DATA.to_vec() },
            Icon { width: 48, height: 48, data: PIXMAP_IDLE_48_DATA.to_vec() },
        ],
        State::Syncing => vec![
            Icon { width: 16, height: 16, data: PIXMAP_SYNCING_16_DATA.to_vec() },
            Icon { width: 22, height: 22, data: PIXMAP_SYNCING_22_DATA.to_vec() },
            Icon { width: 24, height: 24, data: PIXMAP_SYNCING_24_DATA.to_vec() },
            Icon { width: 32, height: 32, data: PIXMAP_SYNCING_32_DATA.to_vec() },
            Icon { width: 48, height: 48, data: PIXMAP_SYNCING_48_DATA.to_vec() },
        ],
        State::Paused => vec![
            Icon { width: 16, height: 16, data: PIXMAP_PAUSED_16_DATA.to_vec() },
            Icon { width: 22, height: 22, data: PIXMAP_PAUSED_22_DATA.to_vec() },
            Icon { width: 24, height: 24, data: PIXMAP_PAUSED_24_DATA.to_vec() },
            Icon { width: 32, height: 32, data: PIXMAP_PAUSED_32_DATA.to_vec() },
            Icon { width: 48, height: 48, data: PIXMAP_PAUSED_48_DATA.to_vec() },
        ],
        State::NeedsLogin => vec![
            Icon { width: 16, height: 16, data: PIXMAP_ATTENTION_16_DATA.to_vec() },
            Icon { width: 22, height: 22, data: PIXMAP_ATTENTION_22_DATA.to_vec() },
            Icon { width: 24, height: 24, data: PIXMAP_ATTENTION_24_DATA.to_vec() },
            Icon { width: 32, height: 32, data: PIXMAP_ATTENTION_32_DATA.to_vec() },
            Icon { width: 48, height: 48, data: PIXMAP_ATTENTION_48_DATA.to_vec() },
        ],
        State::Offline => vec![
            Icon { width: 16, height: 16, data: PIXMAP_OFFLINE_16_DATA.to_vec() },
            Icon { width: 22, height: 22, data: PIXMAP_OFFLINE_22_DATA.to_vec() },
            Icon { width: 24, height: 24, data: PIXMAP_OFFLINE_24_DATA.to_vec() },
            Icon { width: 32, height: 32, data: PIXMAP_OFFLINE_32_DATA.to_vec() },
            Icon { width: 48, height: 48, data: PIXMAP_OFFLINE_48_DATA.to_vec() },
        ],
    }
}

